const headers = $input.first().json.headers || {};
const body = $input.first().json.body;
const event = body.event || {};

// Ignore Slack retries
if (headers['x-slack-retry-num']) {
  return [];
}

// Ignore bot messages and message updates to prevent loops
if (event.bot_id || event.subtype) {
  return [];
}

const eventType = event.type;
const isThreadReply = event.thread_ts && event.thread_ts !== event.ts;
const isReaction = eventType === 'reaction_added';
const isDM = event.channel_type === 'im';
const hasBotMention = (event.text || '').includes('<@');

// Extract message text and remove bot mention
let text = (event.text || '').trim();
const textLower = text.toLowerCase().replace(/<@[A-Z0-9]+>/gi, '').trim();

// Determine event category
let category = 'unknown';
let command = null;

if (isReaction && event.reaction === 'white_check_mark') {
  category = 'resolve_decision';
} else if (isThreadReply && !isDM) {
  // Thread reply in channel - could be decision discussion or question followup
  category = 'thread_message';
} else if (textLower.includes('decisions') || textLower.includes('decisiones')) {
  category = 'command';
  command = 'decisions';
} else if (textLower.includes('help') || textLower.includes('ayuda')) {
  category = 'command';
  command = 'help';
} else if (isDM || hasBotMention) {
  // General question - DM (including thread replies in DM) or mention
  category = 'general_question';
}

return [{
  json: {
    category,
    command,
    channel: event.channel || event.item?.channel,
    user: event.user,
    text: text,
    thread_ts: event.thread_ts || event.ts,
    message_ts: event.ts,
    reaction: event.reaction,
    item_ts: event.item?.ts,
    event_type: eventType,
    is_dm: isDM,
    is_thread_reply: isThreadReply
  }
}];

const files = $input.all();
const mdFiles = files.filter(f => f.json.name && f.json.name.endsWith('.md'));

if (mdFiles.length === 0) {
  return [{ json: { files: [], hasFiles: false } }];
}

return mdFiles.map(f => ({ json: { path: f.json.path, name: f.json.name } }));

const items = $input.all();
const openDecisions = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  let content;

  if (item.binary && item.binary.data) {
    try {
      const binaryData = await this.helpers.getBinaryDataBuffer(i, 'data');
      content = binaryData.toString('utf8');
    } catch (e) {
      continue;
    }
  } else {
    continue;
  }

  const fmMatch = content.match(/^---\n([\s\S]*?)\n---/);
  if (!fmMatch) continue;

  const lines = fmMatch[1].split('\n');
  const frontmatter = {};
  for (const line of lines) {
    const colonIndex = line.indexOf(':');
    if (colonIndex > 0) {
      const key = line.slice(0, colonIndex).trim();
      const value = line.slice(colonIndex + 1).trim().replace(/^["']|["']$/g, '');
      frontmatter[key] = value;
    }
  }

  if (frontmatter.status === 'open') {
    openDecisions.push({
      id: frontmatter.id || 'unknown',
      title: frontmatter.title || 'Sin título',
      created: frontmatter.created || '',
      path: item.json.path
    });
  }
}

return [{ json: { openDecisions, count: openDecisions.length } }];

const { openDecisions, count } = $input.first().json;
const channel = $('Parse Event').first().json.channel;

let text, blocks;

if (count === 0) {
  text = 'No hay decisiones abiertas';
  blocks = [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: '*No hay decisiones abiertas* :white_check_mark:'
      }
    }
  ];
} else {
  text = `Hay ${count} decisión(es) abierta(s)`;
  blocks = [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: `Decisiones Abiertas (${count})`,
        emoji: true
      }
    }
  ];

  for (const decision of openDecisions) {
    blocks.push({
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*${decision.id}*: ${decision.title}`
      },
      accessory: {
        type: 'button',
        text: {
          type: 'plain_text',
          text: 'Ver detalle',
          emoji: true
        },
        value: JSON.stringify({ id: decision.id, path: decision.path, title: decision.title }),
        action_id: `view_decision_${decision.id}`
      }
    });
  }
}

return [{ json: { channel, text, blocks } }];

const channel = $('Parse Event').first().json.channel;

const text = 'Comandos disponibles';
const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: 'Akne - Ayuda',
      emoji: true
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Comandos disponibles:*'
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '• `decisions` o `decisiones` - Lista las decisiones de negocio abiertas'
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '• `help` o `ayuda` - Muestra este mensaje de ayuda'
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '• Responde en el hilo de una decisión para discutirla conmigo'
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '• Pon :white_check_mark: en un hilo para cerrar la decisión'
    }
  },
  {
    type: 'divider'
  },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: 'Puedes mencionarme en cualquier canal o enviarme un mensaje directo'
      }
    ]
  }
];

return [{ json: { channel, text, blocks } }];

// Slack sends interaction payload as form-urlencoded with 'payload' field
const body = $input.first().json.body;
let payload;

if (typeof body === 'string') {
  payload = JSON.parse(body);
} else if (body.payload) {
  payload = JSON.parse(body.payload);
} else {
  payload = body;
}

const action = payload.actions && payload.actions[0];
if (!action) {
  return [];
}

const actionId = action.action_id || '';
const value = action.value ? JSON.parse(action.value) : {};

return [{
  json: {
    action_id: actionId,
    decision_id: value.id,
    decision_path: value.path,
    decision_title: value.title,
    channel: payload.channel?.id || payload.container?.channel_id,
    user: payload.user?.id,
    message_ts: payload.message?.ts,
    response_url: payload.response_url
  }
}];

const item = $input.first();
const interactionData = $('Parse Interaction').first().json;

let content;
if (item.binary && item.binary.data) {
  const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
  content = binaryData.toString('utf8');
} else {
  return [{ json: { error: 'No content' } }];
}

// Parse frontmatter
const fmMatch = content.match(/^---\n([\s\S]*?)\n---/);
const frontmatterRaw = fmMatch ? fmMatch[1] : '';
const bodyContent = fmMatch ? content.slice(fmMatch[0].length).trim() : content;

// Parse YAML
const lines = frontmatterRaw.split('\n');
const frontmatter = {};
for (const line of lines) {
  const colonIndex = line.indexOf(':');
  if (colonIndex > 0) {
    const key = line.slice(0, colonIndex).trim();
    const value = line.slice(colonIndex + 1).trim().replace(/^["']|["']$/g, '');
    frontmatter[key] = value;
  }
}

// Extract sections
function extractSection(name) {
  const regex = new RegExp(`## ${name}\\s*\\n([\\s\\S]*?)(?=\\n## |$)`, 'i');
  const match = bodyContent.match(regex);
  return match ? match[1].trim() : '';
}

const context = extractSection('Contexto') || extractSection('Context');
const options = extractSection('Opciones') || extractSection('Options');
const question = extractSection('Pregunta') || extractSection('Question');

const githubUrl = `https://github.com/elevenyellow/akne/blob/main/${interactionData.decision_path}`;

return [{
  json: {
    channel: interactionData.channel,
    decision_id: interactionData.decision_id,
    decision_path: interactionData.decision_path,
    title: frontmatter.title || interactionData.decision_title,
    status: frontmatter.status,
    resolver: frontmatter.resolver,
    context,
    options,
    question,
    full_content: content,
    github_url: githubUrl,
    message_ts: interactionData.message_ts
  }
}];

const data = $('Parse Decision Detail').first().json;

// Truncate long text for Slack limits
const truncate = (text, max = 2500) => {
  if (!text) return '_No especificado_';
  if (text.length <= max) return text;
  return text.slice(0, max) + '...';
};

// Convert markdown bold (**text**) to Slack bold (*text*)
const toSlack = (text) => {
  if (!text) return '_No especificado_';
  return text.replace(/\*\*(.+?)\*\*/g, '*$1*');
};

const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: `${data.decision_id}: ${data.title}`,
      emoji: true
    }
  },
  {
    type: 'section',
    fields: [
      {
        type: 'mrkdwn',
        text: `*Estado:* ${data.status || 'open'}`
      },
      {
        type: 'mrkdwn', 
        text: `*Resolver:* ${data.resolver || 'No asignado'}`
      }
    ]
  },
  {
    type: 'divider'
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Contexto*`
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: toSlack(truncate(data.context))
    }
  },
  {
    type: 'divider'
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Opciones*`
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: toSlack(truncate(data.options))
    }
  },
  {
    type: 'divider'
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Pregunta*`
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: toSlack(truncate(data.question))
    }
  },
  {
    type: 'divider'
  },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: `<${data.github_url}|Ver en GitHub> | Responde en este hilo para discutir | :white_check_mark: para cerrar`
      }
    ]
  }
];

// No thread_ts - cada detalle es un mensaje nuevo que inicia su propio thread
return [{
  json: {
    channel: data.channel,
    text: `Detalle de ${data.decision_id}: ${data.title}`,
    blocks
  }
}];

const decisionData = $('Lookup Thread Decision').first().json;
const threadData = $input.first().json;
const eventData = $('Parse Event').first().json;

const messages = threadData.messages || [];

// Build conversation history for Claude
const conversationHistory = messages
  .filter(m => !m.bot_id) // Exclude bot messages from history to Claude
  .map(m => ({
    role: 'user',
    content: m.text
  }));

// Get the latest user message
const latestMessage = eventData.text;

return [{
  json: {
    decision_id: decisionData.decision_id,
    decision_context: decisionData.decision_context,
    file_path: decisionData.file_path,
    channel: eventData.channel,
    thread_ts: eventData.thread_ts,
    user: eventData.user,
    latest_message: latestMessage,
    conversation_history: conversationHistory
  }
}];

const fileData = $('Fetch Decision for Resolve').first().json;
const threadData = $input.first().json;

// Decode decision content from base64
const decisionContent = Buffer.from(fileData.content, 'base64').toString('utf8');

// Build conversation from thread messages
const messages = threadData.messages || [];
const conversation = messages.map(m => (m.bot_id ? '[Bot]' : '[Usuario]') + ': ' + m.text).join('\n');

// Build the prompt for Claude
const prompt = `Eres un asistente que documenta decisiones de negocio.

A continuación tienes el contenido de un documento de decisión y la conversación del equipo en Slack donde se discutió y resolvió.

## Documento de decisión:
${decisionContent}

## Conversación en Slack:
${conversation}

---

Basándote en la conversación, genera un resumen conciso (2-4 frases) de la decisión tomada para la sección "## Decisión" del documento.

Formato requerido:
- Primera línea: La opción elegida y una breve justificación
- Segunda línea: Fecha en formato YYYY-MM-DD
- Si se menciona dónde queda reflejada, incluir el enlace

Responde SOLO con el texto para la sección Decisión, sin explicaciones adicionales.`;

return [{
  json: {
    prompt,
    decisionContent,
    conversation
  }
}];

const fileData = $('Fetch Decision for Resolve').first().json;
const decisionData = $('Lookup Decision by Reaction').first().json;
const eventData = $('Parse Event').first().json;
const summaryResponse = $input.first().json;

// Decode content from base64
const content = Buffer.from(fileData.content, 'base64').toString('utf8');

// Get the decision summary from Claude
const decisionSummary = summaryResponse.content[0].text;

// Update status from open to decided
let updatedContent = content.replace(/^(status:\s*)open/m, '$1decided');

// Replace the Decisión section
const decisionSectionRegex = /(## Decisión\n)[\s\S]*?(?=\n## |\n<!-- |$)/;
if (decisionSectionRegex.test(updatedContent)) {
  updatedContent = updatedContent.replace(decisionSectionRegex, `$1${decisionSummary}\n\n`);
} else {
  // If no Decisión section, append it
  updatedContent += `\n## Decisión\n${decisionSummary}\n`;
}

// Extract title for confirmation message
const titleMatch = content.match(/^title:\s*["']?(.+?)["']?$/m);
const title = titleMatch ? titleMatch[1] : decisionData.decision_id;

// Get file SHA from GitHub response
const fileSha = fileData.sha;

// Encode updated content to base64 for GitHub API
const updatedContentBase64 = Buffer.from(updatedContent).toString('base64');

return [{
  json: {
    decision_id: decisionData.decision_id,
    file_path: decisionData.file_path,
    file_sha: fileSha,
    title: title,
    decision_summary: decisionSummary,
    original_content: content,
    updated_content: updatedContent,
    updated_content_base64: updatedContentBase64,
    channel: eventData.channel,
    thread_ts: decisionData.slack_thread_ts,
    user_id: eventData.user
  }
}];

// Try to get input from thread context first, then fall back to Route Event
let input;
let threadHistory = [];

try {
  input = $('Prepare Thread Context').first().json;
  threadHistory = input.thread_history || [];
} catch (e) {
  input = $('Route Event').first().json;
}

const readmeResponse = $input.first().json;

// Decode README content
const readmeContent = Buffer.from(readmeResponse.content, 'base64').toString('utf-8');

// Clean question text (remove bot mention)
const question = (input.current_question || input.text || '').replace(/<@[A-Z0-9]+>/gi, '').trim();

// Build system prompt
const systemPrompt = `Eres Akne, el mentor técnico del proyecto AKNE - una plataforma de teledermatología. Tienes un conocimiento profundo del proyecto y su historia.

Tu personalidad:
- Guía experta y paciente
- Conoces el contexto histórico de cada decisión
- Explicas el 'por qué' detrás de las cosas
- Usas analogías cuando ayudan a clarificar
- Respondes en el idioma de la pregunta (español o inglés)
- Eres conciso pero completo

FORMATO DE RESPUESTA (MUY IMPORTANTE):
- Usa formato Slack, NO markdown estándar
- Para negrita: *texto* (un solo asterisco a cada lado)
- Para cursiva: _texto_
- Para código inline: \`código\`
- Para bloques de código: \`\`\`código\`\`\`
- NO uses ## o # para títulos, usa *Título* en negrita seguido de nueva línea
- NO uses **texto** para negrita, usa *texto*
- Usa bullet points con • o -
- Usa líneas vacías para separar secciones

Tienes acceso a la documentación del proyecto. Aquí está el mapa de docs:

${readmeContent}

Puedes usar la tool 'read_doc' para leer cualquier archivo de docs/ cuando necesites más contexto. Los paths relativos empiezan desde la raíz del repo (ej: docs/strategy/vision.md).`;

// Build messages array - include thread history if available
const messages = [
  ...threadHistory,
  { role: 'user', content: question }
];

// Build Claude request body
const claudeBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 2048,
  system: systemPrompt,
  tools: [{
    name: 'read_doc',
    description: 'Lee un archivo de documentación del repo. Usa paths como docs/strategy/vision.md, docs/product/actors.md, etc.',
    input_schema: {
      type: 'object',
      properties: {
        path: {
          type: 'string',
          description: 'Path del archivo relativo a la raíz del repo, ej: docs/strategy/vision.md'
        }
      },
      required: ['path']
    }
  }],
  messages: messages
};

return [{
  json: {
    channel: input.channel,
    thread_ts: input.thread_ts || input.message_ts,
    user: input.user,
    question: question,
    claude_body: claudeBody,
    has_history: threadHistory.length > 0
  }
}];

const response = $input.first().json;
const toolUse = response.content.find(c => c.type === 'tool_use');

if (!toolUse) {
  throw new Error('No tool_use block found');
}

return [{
  json: {
    tool_use_id: toolUse.id,
    tool_name: toolUse.name,
    file_path: toolUse.input.path,
    previous_response: response
  }
}];

const toolCall = $('Extract Tool Call').first().json;
const docResponse = $input.first().json;
const context = $('Prepare Question Context').first().json;
const previousResponse = toolCall.previous_response;

// Decode doc content
let docContent;
try {
  if (Array.isArray(docResponse)) {
    const files = docResponse.map(f => f.name + (f.type === 'dir' ? '/' : '')).join('\n');
    docContent = `This is a directory. Contents:\n${files}\n\nTry requesting a specific file like ${toolCall.file_path}/README.md`;
  } else if (docResponse.content) {
    docContent = Buffer.from(docResponse.content, 'base64').toString('utf-8');
  } else if (docResponse.message) {
    docContent = 'Error: ' + docResponse.message + ' at path: ' + toolCall.file_path;
  } else {
    docContent = 'Error: Could not read file at ' + toolCall.file_path;
  }
} catch (e) {
  docContent = 'Error: Could not read file at ' + toolCall.file_path + ' - ' + e.message;
}

// Get original messages from claude_body and add the tool interaction
const originalMessages = context.claude_body.messages;
const messages = [
  ...originalMessages,
  { role: 'assistant', content: previousResponse.content },
  { role: 'user', content: [{
    type: 'tool_result',
    tool_use_id: toolCall.tool_use_id,
    content: docContent
  }]}
];

// Reuse the claude_body from context which has the tools
const claudeBody = {
  ...context.claude_body,
  messages: messages
};

return [{
  json: {
    channel: context.channel,
    thread_ts: context.thread_ts,
    claude_body: claudeBody
  }
}];

const response = $input.first().json;
let context;
let claude_body;

// Get context from appropriate source - check loop path first
try {
  // Try loop path first (Prepare Next Tool Result)
  context = $('Prepare Next Tool Result').first().json;
  claude_body = context.claude_body;
} catch (e) {
  try {
    // Then try first tool call path
    context = $('Prepare Tool Result').first().json;
    claude_body = context.claude_body;
  } catch (e2) {
    // Finally try initial path (no tool calls yet)
    context = $('Prepare Question Context').first().json;
    claude_body = context.claude_body;
  }
}

// Check if Claude wants to use another tool
if (response.stop_reason === 'tool_use') {
  // Extract tool use for another round
  const toolUse = response.content.find(c => c.type === 'tool_use');
  if (toolUse) {
    return [{
      json: {
        needs_another_tool: true,
        tool_use_id: toolUse.id,
        tool_name: toolUse.name,
        file_path: toolUse.input.path,
        previous_response: response,
        channel: context.channel,
        thread_ts: context.thread_ts,
        claude_body: claude_body
      }
    }];
  }
}

// Extract text response
const textBlock = response.content.find(c => c.type === 'text');
let responseText = textBlock ? textBlock.text : 'No pude generar una respuesta.';

// Convert any remaining markdown to Slack format
responseText = responseText
  .replace(/\*\*(.+?)\*\*/g, '*$1*')  // **bold** -> *bold*
  .replace(/^##\s+(.+)$/gm, '*$1*')      // ## Title -> *Title*
  .replace(/^#\s+(.+)$/gm, '*$1*');       // # Title -> *Title*

return [{
  json: {
    needs_another_tool: false,
    channel: context.channel,
    thread_ts: context.thread_ts,
    response: responseText
  }
}];

const prevResult = $('Format Question Response').first().json;
const docResponse = $input.first().json;
const context = $('Prepare Question Context').first().json;

// Decode doc content - handle files vs directories
let docContent;
try {
  if (Array.isArray(docResponse)) {
    // GitHub returned a directory listing
    const files = docResponse.map(f => f.name + (f.type === 'dir' ? '/' : '')).join('\n');
    docContent = `This is a directory. Contents:\n${files}\n\nTry requesting a specific file like ${prevResult.file_path}/README.md`;
  } else if (docResponse.content) {
    docContent = Buffer.from(docResponse.content, 'base64').toString('utf-8');
  } else if (docResponse.message) {
    // GitHub API error (e.g., Not Found)
    docContent = 'Error: ' + docResponse.message + ' at path: ' + prevResult.file_path;
  } else {
    docContent = 'Error: Could not read file at ' + prevResult.file_path;
  }
} catch (e) {
  docContent = 'Error: Could not read file at ' + prevResult.file_path + ' - ' + e.message;
}

// Get the previous claude_body and add the new messages
const prevBody = prevResult.claude_body;
const newMessages = [
  ...prevBody.messages,
  { role: 'assistant', content: prevResult.previous_response.content },
  { role: 'user', content: [{
    type: 'tool_result',
    tool_use_id: prevResult.tool_use_id,
    content: docContent
  }]}
];

// Build new Claude request body
const claudeBody = {
  model: prevBody.model,
  max_tokens: prevBody.max_tokens,
  system: prevBody.system,
  tools: prevBody.tools,
  messages: newMessages
};

return [{
  json: {
    channel: context.channel,
    thread_ts: context.thread_ts,
    claude_body: claudeBody
  }
}];

const input = $('Route Event').first().json;
const threadData = $input.first().json;

// Bot user ID for Akne
const BOT_USER_ID = 'U08TRU0H9NZ';

if (!threadData.ok || !threadData.messages) {
  // Can't fetch thread, skip
  return [];
}

const messages = threadData.messages;

// Check if bot participated in this thread
const botParticipated = messages.some(m => m.user === BOT_USER_ID || m.bot_id);

if (!botParticipated) {
  // Bot hasn't been in this thread, ignore
  return [];
}

// Convert thread history to conversation format for Claude
const conversation = messages
  .filter(m => !m.subtype) // Skip system messages
  .map(m => {
    const isBot = m.user === BOT_USER_ID || m.bot_id;
    const text = (m.text || '').replace(/<@[A-Z0-9]+>/gi, '').trim();
    return {
      role: isBot ? 'assistant' : 'user',
      content: text
    };
  })
  .filter(m => m.content); // Skip empty messages

// Remove the last message if it's from user (that's the current question)
const lastMsg = conversation[conversation.length - 1];
let currentQuestion = input.text.replace(/<@[A-Z0-9]+>/gi, '').trim();
if (lastMsg && lastMsg.role === 'user') {
  conversation.pop();
}

return [{
  json: {
    ...input,
    thread_history: conversation,
    current_question: currentQuestion
  }
}];
